import os
import hmac
import hashlib
import sqlite3
import secrets
from flask import Flask, request, session, redirect, jsonify, g
from functools import wraps
import bleach
import re

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

DB_PATH = os.environ.get('DB_PATH', '/var/app/data/users.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        entry TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()

def hash_password(password, salt):
    """Derive a password hash using PBKDF2 with a per-user salt."""
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()

def sanitize_input(value):
    """Sanitize user input - strip dangerous characters for display"""
    if not isinstance(value, str):
        return str(value)
    # Remove null bytes and control characters
    value = re.sub(r'[\x00-\x1f\x7f]', '', value)
    # Limit length
    return value[:256]

def write_audit_log(event, username, action, **kwargs):
    """Write an entry to the audit log with structured formatting.

    Uses safe string formatting with explicit field access only.
    All fields are sanitized before inclusion.
    """
    from datetime import datetime

    # Sanitize the core fields to prevent log injection
    safe_username = sanitize_input(username)
    safe_action = sanitize_input(action)
    safe_event = sanitize_input(event)

    # Sanitize all additional kwargs
    safe_kwargs = {k: sanitize_input(str(v)) for k, v in kwargs.items()}

    # Build the log entry using safe f-string concatenation
    # Never use .format() with user-influenced data in the template
    timestamp = datetime.utcnow().isoformat()

    extra_parts = []
    for k, v in safe_kwargs.items():
        extra_parts.append(f"{k}={v}")
    extra_str = ' '.join(extra_parts)

    entry = f"[{timestamp}] {safe_event}: user={safe_username} action={safe_action}"
    if extra_str:
        entry += f" {extra_str}"

    db = get_db()
    db.execute('INSERT INTO audit_log (entry) VALUES (?)', (entry,))
    db.commit()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            api_key = request.headers.get('X-API-Key')
            if api_key:
                db = get_db()
                user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
                if user:
                    g.current_user = dict(user)
                    return f(*args, **kwargs)
            return jsonify({'error': 'Authentication required'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        if not user:
            return jsonify({'error': 'User not found'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not hasattr(g, 'current_user') or g.current_user.get('role') != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()

    if not user:
        write_audit_log('AUTH_FAILURE', username, 'login_attempt_unknown_user')
        return jsonify({'error': 'Invalid credentials'}), 401

    # Verify password using PBKDF2 with the user's unique per-user salt
    password_hash = hash_password(password, user['salt'])
    if not hmac.compare_digest(password_hash, user['password_hash']):
        write_audit_log('AUTH_FAILURE', username, 'login_attempt_bad_password')
        return jsonify({'error': 'Invalid credentials'}), 401

    session['user_id'] = user['id']
    write_audit_log('AUTH_SUCCESS', username, 'login')
    return jsonify({'message': 'Login successful', 'role': user['role']})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    write_audit_log('ACCESS', user['username'], 'view_profile')
    return jsonify({
        'username': user['username'],
        'role': user['role'],
    })

@app.route('/api/profile', methods=['PUT'])
@require_auth
def update_profile():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    user = g.current_user
    allowed_fields = ['username']

    updates = {}
    for field in allowed_fields:
        if field in data:
            updates[field] = sanitize_input(data[field])

    if not updates:
        return jsonify({'error': 'No valid fields to update'}), 400

    db = get_db()
    for field, value in updates.items():
        db.execute(f'UPDATE users SET {field} = ? WHERE id = ?', (value, user['id']))
    db.commit()

    # Log the profile update with the new values as additional context
    write_audit_log('PROFILE_UPDATE', user['username'], 
                    'update_fields', 
                    new_values=str(updates))

    return jsonify({'message': 'Profile updated'})

@app.route('/api/users/<username>/notes', methods=['POST'])
@require_auth
def add_user_note(username):
    """Add a note/comment about a user (for admin review)"""
    data = request.get_json()
    if not data or 'note' not in data:
        return jsonify({'error': 'Note content required'}), 400

    note_content = data['note']
    author = g.current_user['username']

    # Sanitize note for storage - prevent XSS
    safe_note = bleach.clean(note_content, tags=[], strip=True)

    db = get_db()
    db.execute('''INSERT INTO user_notes (target_username, author, content)
                  VALUES (?, ?, ?)''', (username, author, safe_note))
    db.commit()

    # Audit log the note creation with note preview
    write_audit_log('NOTE_CREATED', author, 
                    'add_note',
                    target=sanitize_input(username),
                    note_preview=sanitize_input(safe_note[:50]))

    return jsonify({'message': 'Note added'})

@app.route('/api/admin/audit', methods=['GET'])
@require_auth
@require_admin
def view_audit_log():
    db = get_db()
    # Safely parse and bound the limit parameter
    try:
        limit = int(request.args.get('limit', 100))
    except (ValueError, TypeError):
        limit = 100
    limit = max(1, min(limit, 1000))
    entries = db.execute('SELECT * FROM audit_log ORDER BY created_at DESC LIMIT ?', 
                        (limit,)).fetchall()
    write_audit_log('ADMIN_ACCESS', g.current_user['username'], 'view_audit_log')
    return jsonify({'entries': [dict(e) for e in entries]})

@app.route('/api/admin/search', methods=['GET'])
@require_auth
@require_admin  
def admin_search():
    """Search users - admin only"""
    query = request.args.get('q', '')
    safe_query = sanitize_input(query)

    db = get_db()
    # Use parameterized query to prevent SQL injection
    users = db.execute(
        'SELECT id, username, role FROM users WHERE username LIKE ?',
        (f'%{safe_query}%',)
    ).fetchall()

    write_audit_log('ADMIN_SEARCH', g.current_user['username'],
                    'search_users', query=safe_query)

    return jsonify({'results': [dict(u) for u in users]})

if __name__ == '__main__':
    with app.app_context():
        init_db()
    app.run(host='127.0.0.1', port=8080, debug=False)
